-- Phong Than 2026-10-04 (content E2): daily login gift + 7-day streak gift. Generated by scratchpad\content\gen_e2.py.
-- Loaded into the servertimer state by ext\dailygift.lua (minute tick over online players: the engine has no usable
-- login hook - player\playerlogin.lua is shadowed by the PAK copy) and, at dialog time, into the Le Quan state
-- (sinhhoat\lq_npc.lua row "Qua dang nhap 7 ngay" -> PTDG_Menu).
-- Tasks: 2541 = yyyymmdd of the last counted day; 2542 = streak (0-7) + 10 * daily gifts pending (0-7)
-- + 100 * 7-day gifts pending (0-3); 2543 = login days in total.
-- A new day is counted at the first tick (or Le Quan talk) of that day: streak + 1 if yesterday was counted (a full
-- streak of 7 starts over at 1), else 1. Each counted day queues one daily gift, day 7 also the big gift.
-- Delivery: only when CalcFreeItemCellCount() covers every row (ceil(n / st) cells per row), else the gift stays
-- queued (nothing is lost; the message repeats every 30 minutes). Items: AddNormalItemPile (VNG tuple, piles,
-- never drops on the ground - KItemList::Add destroys on failure, which the free-cell check prevents).
-- Config admin_bridge\dailygift_config.lua (web admin), else PTDG_DEFAULT. Lua 4, ASCII, TCVN3 escapes.

PTDG_T_DAY = 2541
PTDG_T_INFO = 2542
PTDG_T_TOTAL = 2543
PTDG_CFG_FILE = "admin_bridge\\dailygift_config.lua"
PTDG_MAX_PLAYER = 1200
PTDG_PD_MAX = 7
PTDG_PB_MAX = 3
PTDG_HEAD = "<color=green>Qu\181 \174\168ng nh\203p<color>: "
PTDG_DEFAULT = { enabled = 1, moneyDaily = 20000, moneyBig = 200000, daily = {
		{ g = 1, d = 2, p = 0, lv = 1, se = 0, n = 10, st = 100, name = "\167\185i H\229ng \174\172n" },
		{ g = 1, d = 5, p = 0, lv = 1, se = 0, n = 10, st = 100, name = "\167\185i Ho\181n \174\172n" },
		{ g = 3, d = 28, p = 0, lv = 0, se = 0, n = 1, st = 100, name = "H\229ng Th\241y Tinh" },
	}, big = {
		{ g = 8, d = 1380, p = 0, lv = 0, se = 0, n = 1, st = 1, name = "Buff x2 kinh nghi\214m (24 gi\234)" },
		{ g = 8, d = 139, p = 2, lv = 0, se = 0, n = 5, st = 100, name = "Kh\171ng Th\173 (B\185ch)" },
		{ g = 3, d = 28, p = 0, lv = 0, se = 0, n = 5, st = 100, name = "H\229ng Th\241y Tinh" },
		{ g = 1, d = 2, p = 0, lv = 1, se = 0, n = 30, st = 100, name = "\167\185i H\229ng \174\172n" },
	} }
if PTDG_WARN == nil then PTDG_WARN = {} end
if PTDG_TICKS == nil then PTDG_TICKS = 0 end

function PTDG_No() end

function PTDG_LoadCfg()
	local old = PTDG_CFG
	PTDG_CFG = nil
	local h = openfile(PTDG_CFG_FILE, "r")
	if h then
		closefile(h)
		call(dofile, { PTDG_CFG_FILE }, "x", PTDG_No)
	end
	if type(PTDG_CFG) ~= "table" then
		if h and old then PTDG_CFG = old else PTDG_CFG = PTDG_DEFAULT end
	end
	if type(PTDG_CFG.daily) ~= "table" then PTDG_CFG.daily = {} end
	if type(PTDG_CFG.big) ~= "table" then PTDG_CFG.big = {} end
end

function PTDG_MDays(y, m)
	if m == 2 then
		if (mod(y, 4) == 0 and mod(y, 100) ~= 0) or mod(y, 400) == 0 then return 29 end
		return 28
	end
	if m == 4 or m == 6 or m == 9 or m == 11 then return 30 end
	return 31
end

-- yyyymmdd of the day before (Lua 4 date() only formats the current time)
function PTDG_Prev(ymd)
	local y = floor(ymd / 10000)
	local m = mod(floor(ymd / 100), 100)
	local d = mod(ymd, 100) - 1
	if d < 1 then
		m = m - 1
		if m < 1 then m = 12 y = y - 1 end
		d = PTDG_MDays(y, m)
	end
	return y * 10000 + m * 100 + d
end

function PTDG_Info()
	local v = GetTask(PTDG_T_INFO)
	return mod(v, 10), mod(floor(v / 10), 10), floor(v / 100)
end

function PTDG_SetInfo(s, pd, pb)
	SetTask(PTDG_T_INFO, s + pd * 10 + pb * 100)
end

-- count today for the current player; returns 1 when a new day was counted
function PTDG_Count(today)
	local d = GetTask(PTDG_T_DAY)
	if d == today then return 0 end
	local s, pd, pb = PTDG_Info()
	if d == PTDG_Prev(today) and s < 7 then s = s + 1 else s = 1 end
	pd = pd + 1
	if pd > PTDG_PD_MAX then pd = PTDG_PD_MAX end
	if s == 7 then
		pb = pb + 1
		if pb > PTDG_PB_MAX then pb = PTDG_PB_MAX end
	end
	SetTask(PTDG_T_DAY, today)
	local tot = GetTask(PTDG_T_TOTAL) + 1
	SetTask(PTDG_T_TOTAL, tot)
	PTDG_SetInfo(s, pd, pb)
	local t = PTDG_HEAD .. "Ng\181y \174\168ng nh\203p th\248 " .. s .. "/7 li\170n ti\213p (t\230ng " .. tot .. " ng\181y)."
	if s == 7 then t = t .. " \167\241 7 ng\181y: c\227 th\170m qu\181 l\237n!" end
	Msg2Player(t)
	return 1
end

function PTDG_Need(list)
	local n = 0
	local k = 1
	while list[k] do
		local e = list[k]
		local st = tonumber(e.st) or 1
		if st < 1 then st = 1 end
		local c = tonumber(e.n) or 1
		if c > 0 then n = n + floor((c + st - 1) / st) end
		k = k + 1
	end
	return n
end

function PTDG_Names(list, money)
	local s = ""
	local k = 1
	while list[k] do
		local e = list[k]
		if s ~= "" then s = s .. ", " end
		s = s .. (e.name or "?") .. " x" .. (e.n or 1)
		k = k + 1
	end
	if money and money > 0 then
		if s ~= "" then s = s .. ", " end
		s = s .. money .. " l\173\238ng"
	end
	return s
end

function PTDG_GiveList(list, money)
	local got = 0
	local k = 1
	while list[k] do
		local e = list[k]
		local c = tonumber(e.n) or 1
		local j = 1
		while j <= c do
			local r = AddNormalItemPile(e.g, e.d, e.p or 0, e.lv or 0, e.se or 0, 0)
			if r and r > 0 then got = got + 1 end
			j = j + 1
		end
		k = k + 1
	end
	if money and money > 0 then Earn(money) end
	return got
end

-- deliver queued gifts to the current player; returns cells missing (0 = nothing left)
function PTDG_Deliver()
	local cfg = PTDG_CFG
	local s, pd, pb = PTDG_Info()
	local nd = PTDG_Need(cfg.daily)
	while pd > 0 do
		if CalcFreeItemCellCount() < nd then return nd end
		pd = pd - 1
		PTDG_SetInfo(s, pd, pb)
		PTDG_GiveList(cfg.daily, tonumber(cfg.moneyDaily) or 0)
		Msg2Player(PTDG_HEAD .. "Nh\203n qu\181 \174\168ng nh\203p h\187ng ng\181y: " .. PTDG_Names(cfg.daily, tonumber(cfg.moneyDaily) or 0))
	end
	local nb = PTDG_Need(cfg.big)
	while pb > 0 do
		if CalcFreeItemCellCount() < nb then return nb end
		pb = pb - 1
		PTDG_SetInfo(s, pd, pb)
		PTDG_GiveList(cfg.big, tonumber(cfg.moneyBig) or 0)
		Msg2Player(PTDG_HEAD .. "Nh\203n qu\181 \174\168ng nh\203p 7 ng\181y li\170n ti\213p: " .. PTDG_Names(cfg.big, tonumber(cfg.moneyBig) or 0))
	end
	return 0
end

function PTDG_Player(today, nm)
	PTDG_Count(today)
	local miss = PTDG_Deliver()
	if miss > 0 then
		local w = PTDG_WARN[nm]
		if not w or PTDG_TICKS - w >= 30 then
			PTDG_WARN[nm] = PTDG_TICKS
			Msg2Player(PTDG_HEAD .. "H\181nh trang kh\171ng \174\241 ch\231 (c\199n " .. miss .. " \171 tr\232ng). Qu\181 \174\173\238c gi\247 l\185i, d\228n t\243i r\229i \174\238i 1 ph\243t ho\198c g\198p L\212 Quan \174\211 nh\203n.")
		end
	else
		PTDG_WARN[nm] = nil
	end
end

function PTDG_Tick(today)
	PTDG_LoadCfg()
	PTDG_TICKS = PTDG_TICKS + 1
	if PTDG_CFG.enabled ~= 1 then return 0 end
	today = today or tonumber(date("%Y%m%d"))
	local n = 0
	local old = PlayerIndex
	local i = 1
	while i <= PTDG_MAX_PLAYER do
		PlayerIndex = i
		local nm = GetName()
		if nm and nm ~= "" then
			PTDG_Player(today, nm)
			n = n + 1
		end
		i = i + 1
	end
	PlayerIndex = old
	return n
end

-- Le Quan row "Qua dang nhap 7 ngay" (dialog of the current player)
function PTDG_Menu()
	PTDG_LoadCfg()
	if PTDG_CFG.enabled ~= 1 then
		Say(PTDG_HEAD .. "Qu\181 \174\168ng nh\203p \174ang t\185m t\190t.", 1, "\167\227ng/PTDG_No")
		return
	end
	local today = tonumber(date("%Y%m%d"))
	PTDG_Count(today)
	local miss = PTDG_Deliver()
	local s, pd, pb = PTDG_Info()
	local t = PTDG_HEAD .. "Chu\231i \174\168ng nh\203p: " .. s .. "/7 ng\181y li\170n ti\213p. T\230ng: " .. GetTask(PTDG_T_TOTAL) .. " ng\181y. Qu\181 \174ang gi\247: " .. pd .. " qu\181 ng\181y, " .. pb .. " qu\181 7 ng\181y."
	if miss > 0 then t = t .. " " .. "H\181nh trang kh\171ng \174\241 ch\231 (c\199n " .. miss .. " \171 tr\232ng). Qu\181 \174\173\238c gi\247 l\185i, d\228n t\243i r\229i \174\238i 1 ph\243t ho\198c g\198p L\212 Quan \174\211 nh\203n." end
	t = t .. "<enter>Qu\181 m\231i ng\181y: " .. PTDG_Names(PTDG_CFG.daily, tonumber(PTDG_CFG.moneyDaily) or 0)
	t = t .. "<enter>Qu\181 ng\181y th\248 7: " .. PTDG_Names(PTDG_CFG.big, tonumber(PTDG_CFG.moneyBig) or 0)
	Say(t, 1, "\167\227ng/PTDG_No")
end
